 @Override public void onLoad(){try{if(!Files.exists(Path.of("ALLOW_DISPOSABLE_RAID_PROBE")))return;Path folder=getDataFolder().toPath();String stage=!Files.exists(folder.resolve("first-passed.txt"))?"first":!Files.exists(folder.resolve("broken-passed.txt"))?"broken":"restart";Path capture=folder.resolve(stage+"-before-plugins");Files.createDirectories(capture);var report=new StringBuilder();for(var path:Map.of("NeverLandTownyContracts","server-materials.db","NeverLandTownySpecialization","production.sqlite").entrySet())for(String suffix:List.of("","-wal","-shm")){Path file=folder.getParent().resolve(path.getKey()).resolve(path.getValue()+suffix);if(Files.exists(file)){byte[] bytes=Files.readAllBytes(file);Files.write(capture.resolve(path.getValue()+suffix),bytes);report.append(file.getFileName()).append(" size=").append(bytes.length).append(" sha256=").append(HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(bytes))).append('\n');}}Files.writeString(capture.resolve("files.txt"),report.toString());}catch(Exception error){throw new RuntimeException(error);}}
