 Town makeTown(UUID id,UUID resident,String name,String player,int chunk)throws Exception{var u=TownyUniverse.getInstance();u.newTownInternal(name,id);var t=TownyAPI.getInstance().getTown(id);var r=TownyAPI.getInstance().getResident(resident);if(r==null)r=u.getDataSource().newResident(player,resident);r.setTown(t);t.setMayor(r);r.save();var block=new TownBlock(chunk,0,u.getWorld(world.getName()));u.addTownBlock(block);block.setTown(t);t.setHomeBlock(block);block.save();t.setSpawn(origin);t.save();return t;}
